311.     /// <param name="comparedTo">The reference date (typically DateTime.UtcNow).</param>
312.     /// <returns>A human-readable string representing the time difference.</returns>
313.     public string Humanize(DateTime input, DateTime comparedTo)
314.     {
315.         var difference = comparedTo - input;
316.         if (Math.Abs(difference.TotalSeconds) < 2)
317.         {
318.             return "just now";
319.         }
320. 
321.         var isFuture = difference.TotalSeconds < 0;
322.         var absDiff = difference.Duration();
323. 
324.         var result = absDiff.TotalDays switch
325.         {
326.             >= 365 => $"{(int)(absDiff.TotalDays / 365)} years",
327.             >= 31 => $"{(int)(absDiff.TotalDays / 30)} months",
328.             >= 1 => $"{(int)absDiff.TotalDays} days",
