330.             {
331.                 >= 1 => $"{(int)absDiff.TotalHours} hours",
332.                 _ => absDiff.TotalMinutes switch
333.                 {
334.                     >= 1 => $"{(int)absDiff.TotalMinutes} minutes",
335.                     _ => $"{(int)absDiff.TotalSeconds} seconds"
336.                 }
337.             }
338.         };
339. 
340.         return isFuture ? $"in {result}" : $"{result} ago";
341.     }
