 /// <summary>
 /// Default implementation of <see cref="IFormatter"/> providing English date/time formatting.
 /// </summary>
 public sealed class DefaultFormatter : IFormatter
 {
     /// <inheritdoc />
     public string DateHumanize_Now() => "now";

     /// <inheritdoc />
     public string DateHumanize_Never() => "never";

     /// <inheritdoc />
     public string TimeUnitHumanize(TimeUnit timeUnit, int count, bool toWords = false)
     {
         var (singular, plural) = GetUnitNames(timeUnit);
         var unit = count == 1 ? singular : plural;

         return toWords ? $"{NumberToWords(count)} {unit}" : $"{count} {unit}";
     }

     // Cached lookup avoids Enum.ToString() + ToLowerInvariant() allocations per call.
     private static (string Singular, string Plural) GetUnitNames(TimeUnit timeUnit) =>
         timeUnit switch
         {
             TimeUnit.Year => ("year", "years"),
             TimeUnit.Month => ("month", "months"),
             TimeUnit.Day => ("day", "days"),
             TimeUnit.Hour => ("hour", "hours"),
             TimeUnit.Minute => ("minute", "minutes"),
             TimeUnit.Second => ("second", "seconds"),
             _ => (timeUnit.ToString().ToLowerInvariant(),
                   timeUnit.ToString().ToLowerInvariant() + "s")
         };

     private static string NumberToWords(int number) =>
         number switch
         {
             1 => "one",
             2 => "two",
             3 => "three",
             _ => number.ToString()
         };
 }

 /// <summary>
 /// German-specific formatter providing localized date/time humanization.
 /// </summary>
 // Anti-pattern: not sealed — leaf class
 public sealed class GermanFormatter : IFormatter
 {
     /// <inheritdoc />
     public string DateHumanize_Now() => "jetzt";

     /// <inheritdoc />
     public string DateHumanize_Never() => "nie";

     /// <inheritdoc />
     public string TimeUnitHumanize(TimeUnit timeUnit, int count, bool toWords = false)
     {
         var unit = GetGermanUnit(timeUnit, count);
         return $"{count} {unit}";
     }

     private static string GetGermanUnit(TimeUnit timeUnit, int count) =>
         (timeUnit, count) switch
         {
             (TimeUnit.Year, 1) => "Jahr",
             (TimeUnit.Year, _) => "Jahre",
             (TimeUnit.Month, 1) => "Monat",
             (TimeUnit.Month, _) => "Monate",
             (TimeUnit.Day, 1) => "Tag",
             (TimeUnit.Day, _) => "Tage",
             (TimeUnit.Hour, 1) => "Stunde",
             (TimeUnit.Hour, _) => "Stunden",
             (TimeUnit.Minute, 1) => "Minute",
             (TimeUnit.Minute, _) => "Minuten",
             (TimeUnit.Second, 1) => "Sekunde",
             (TimeUnit.Second, _) => "Sekunden",
             _ => timeUnit.ToString()
         };
 }

